#!/bin/sh
# Review 1 of design 26 (Nathan, 2026-10-01). One job on 26-hall-b.pen; the attached image is the LIVE app.
cd /c/Users/vaugh/discord-design
P="Change the Wishlist and Auction frames (keep the other frames) after Nathan's review. The attached image is the LIVE app: use its top bar (the lion logo with LION PRIDE TCG and the icons calendar, ?, bell, trophy, avatar; no week label, no streak) and its Community tabs Trades | Hall | Boons & Pranks (no Board tab). Nathan's words: 1) Profile wishlist: the Closest achievements window is removed, the Raid Boss tile moves down, and the Wishlist is added (as the attached live profile, with that change). 2) Trading Hall: I don't like the rows, can we make them rectangle cards with the card art and then the person underneath the card. Two sections: Wanted (each card is a wishlist card, with the member who wants it under it) and For trade (each card is a card a member lists for anyone to trade for, with that member under it). Clicking into a card shows the details: for a For trade card, what they want for it (their wishlist) and an offer; for a Wanted card, their wishlist and an offer. 3) Offer window: I like seeing the wishlist here vs Kira's Secret Rares. Players never see the other players' cards except the wishlist items: the grid labeled Kira's Secret Rares becomes Kira's Wishlist with the 5 cards Kira picked on the profile. 4) Start an auction / seller: the minimum can be the 2x Full Art kind of rule and/or specific cards: type in a specific card, search for it and select it, on top of the other requirements. 5) Auctions: the card grid of the bidder view is how the Auctions tab and the Trade Hall should look; clicking into a card brings up all the details for that auction and you can submit cards for that auction bid. 6) The Discord notice stays as it is. Sample names only. No scrolling: everything fits 1280 x 720; long lists use the pager (< 1 of 4 >)."
pen --in design/26-hall-b.pen --out design/26-hall-c.pen --prompt "$P" --prompt-file design/images/ref-live-profile.png --export design/26-hall-c.png --export-scale 2 2>&1 | sed 's/\x1b\[[0-9;]*m//g' | tail -3
echo ALL-DONE
